// Configuración: perfil de empresa, depósitos (QR, escaneo, filtros avanzados, acciones en lote, crear uno / secuencia), ubicaciones jerárquicas, usuarios, saldos de apertura, productos enológicos, ayuda.
import { S, $, $$, esc, fmtN, fmtL, fmtD, today, ico, api, reload, toast, go, me, vessel, qs, crumbs, head, empty, kpi, tabs, modal, closeModal, showError, formModal, confirmDialog, vesselPicker, opts, formValues, importModal, downloadCsv, lotPill, KIND, MATERIAL, VTYPE, WINE, PHASE, CATEGORY, GRAIN, TOAST, BARREL_STATUS, LOC_KIND, ROLE, AREA, SUGAR_UNIT } from './core.js';
import { openQr } from './v-bodega.js';

const route = () => window.dispatchEvent(new HashChangeEvent('hashchange'));

// ================================================================ PERFIL
export async function viewProfile(page) {
  crumbs('Configuración', 'Perfil de la empresa');
  const c = (await api('/company')).company; const locked = c.lot_numbering === 'standard';
  const radios = (name, items, cur) => `<div class="type-grid" style="grid-template-columns:repeat(auto-fill,minmax(170px,1fr))">${items.map(([k, l, i, sub]) => `<label class="k-admin"><input type="radio" name="${name}" value="${k}" ${cur === k ? 'checked' : ''}><span class="tile">${ico(i)}</span><span>${l}${sub ? `<br><small class="muted">${sub}</small>` : ''}</span></label>`).join('')}</div>`;
  page.innerHTML = head({ title: 'Perfil de la empresa', icon: 'company', k: 'k-admin', eyebrow: 'Configuración', sub: 'Preferencias y datos de la empresa.', actions: `<button class="btn primary" id="save1">${ico('check')} Guardar</button>` }) +
    `<form id="pf" class="stack">
      <div class="sec-title">Preferencias</div>
      <div class="card"><h3>${ico('eye')}Apariencia</h3>${radios('appearance', [['light', 'Claro', 'sun'], ['dark', 'Oscuro', 'moon'], ['system', 'Sistema', 'grid']], c.appearance || 'system')}</div>
      <div class="card"><h3>${ico('vineyard')}Perfil de actividad</h3><p class="help" style="margin-bottom:10px">Simplifica la barra lateral según su tipo de actividad. No bloquea funciones: todas las páginas siguen siendo accesibles directamente.</p>${radios('profile', [['full', 'Productor completo', 'grid'], ['vineyard', 'Solo viñedo', 'vineyard'], ['winery', 'Solo bodega', 'cellar']], c.profile || 'full')}</div>
      <div class="card"><h3>${ico('thermo')}Unidad de azúcar usada en bodega</h3><p class="help" style="margin-bottom:10px">Se aplica a las lecturas nuevas. Las lecturas anteriores conservan la unidad con la que se registraron.</p>${radios('sugar_unit', [['baume', 'Baumé', 'thermo', '°Bé'], ['brix', 'Brix', 'thermo', '°Bx'], ['density', 'Densidad', 'thermo', 'g/cm³']], c.sugar_unit || 'brix')}</div>
      <div class="sec-title">Empresa</div>
      <div class="card"><div class="row"><label class="field req" style="flex:2"><span>Nombre de la empresa</span><input name="name" value="${esc(c.name || '')}"></label><label class="field"><span>Modo de producción predominante</span><select name="production_mode">${['', 'convencional', 'ecológica', 'biodinámica', 'en conversión'].map((x) => `<option value="${x}" ${x === (c.production_mode || '') ? 'selected' : ''}>${x || '—'}</option>`).join('')}</select></label><label class="field"><span>País</span><select name="country">${[['MX', 'México'], ['US', 'Estados Unidos'], ['ES', 'España'], ['AR', 'Argentina'], ['CL', 'Chile'], ['PT', 'Portugal'], ['FR', 'Francia']].map(([k, l]) => `<option value="${k}" ${(c.country || 'MX') === k ? 'selected' : ''}>${l}</option>`).join('')}</select></label></div>
        <div class="row" style="margin-top:12px"><label class="field" style="flex:2"><span>Dirección</span><input name="address" value="${esc(c.address || '')}"></label><label class="field"><span>Ciudad</span><input name="city" value="${esc(c.city || '')}"></label><label class="field"><span>Estado / Región</span><input name="region" value="${esc(c.region || '')}"></label><label class="field"><span>Código postal</span><input name="postal_code" value="${esc(c.postal_code || '')}"></label></div>
        <div class="row" style="margin-top:12px"><label class="field"><span>RFC</span><input name="tax_id" value="${esc(c.tax_id || '')}"></label><label class="field"><span>Teléfono</span><input name="phone" value="${esc(c.phone || '')}"></label><label class="field"><span>Correo electrónico de la empresa</span><input type="email" name="email" value="${esc(c.email || '')}"></label><label class="field"><span>Superficie total de viñedo (ha)</span><input type="number" step="0.01" inputmode="decimal" name="vineyard_ha" value="${esc(c.vineyard_ha ?? '')}"></label></div></div>
      <div class="sec-title">Numeración de lotes</div>
      <div class="card"><div class="between"><div><b>${locked ? 'Numeración estándar · AA-TT-NNN' : 'Numeración personalizada'}</b><div class="help">${locked ? 'Año corto, abreviatura del tipo de vino y secuencia (p. ej. 26-BL-001).' : `Patrón: <code>${esc(c.lot_pattern || '')}</code>`}</div></div><div style="display:flex;gap:8px"><button type="button" class="btn" id="custom">${ico('edit')} Personalizar la numeración</button>${locked ? '' : `<button type="button" class="btn" id="lock">${ico('shield')} Bloquear</button>`}</div></div>
        <div id="numbox" ${locked ? 'hidden' : ''} style="margin-top:12px"><input type="hidden" name="lot_numbering" value="${c.lot_numbering || 'standard'}"><label class="field"><span>Patrón personalizado</span><input name="lot_pattern" value="${esc(c.lot_pattern || '')}" placeholder="L{YY}{NNNN}" class="mono"><div class="help">Comodines: <code>{YYYY}</code> año, <code>{YY}</code> año corto, <code>{TIPO}</code> abreviatura del vino (TI, BL, RO…), <code>{NNNN}</code> secuencia. Ejemplo: <code>L{YY}{NNNN}</code> → L260001.</div></label></div></div>
      <div class="card"><h3>${ico('sparkle')}Módulos</h3><label class="toggle"><input type="checkbox" name="advanced_modules" ${c.advanced_modules ? 'checked' : ''}> Mostrar módulos avanzados en la barra lateral</label></div>
      <div class="between"><span class="muted small">Los cambios se aplican a toda la bodega.</span><button class="btn primary" type="submit">${ico('check')} Guardar</button></div>
    </form>`;
  const save = async () => { const b = formValues($('#pf')); try { await api('/company', { method: 'PUT', body: b }); toast('Perfil guardado'); document.documentElement.dataset.theme = b.appearance === 'system' ? '' : b.appearance; await reload(); S.advanced = !!b.advanced_modules; localStorage.setItem('ulula.advanced', S.advanced ? '1' : '0'); localStorage.removeItem('ulula.scope'); route(); } catch (err) { toast(err.message, true); } };
  $('#pf').onsubmit = (e) => { e.preventDefault(); save(); }; $('#save1').onclick = save;
  $('#custom').onclick = () => { $('#numbox').hidden = false; $('[name=lot_numbering]').value = 'custom'; $('[name=lot_pattern]').focus(); };
  if ($('#lock')) $('#lock').onclick = () => { $('[name=lot_numbering]').value = 'standard'; save(); };
}

// ================================================================ DEPÓSITOS
export async function viewVessels(page) {
  crumbs('Configuración', 'Depósitos');
  const q = S.route.q; const vs = S.boot.vessels; const locs = S.boot.locations; const adv = q.adv === '1'; const tab = q.tab || '';
  if (tab === 'ubicaciones') { await viewLocations(page, true); return; }
  let rows = vs;
  const filt = { kind: q.kind || '', material: q.material || '', type: q.type || '', loc: q.loc || '', status: q.status || '', occ: q.occ || '', wine: q.wine || '' };
  if (filt.kind) rows = rows.filter((v) => v.kind === filt.kind); if (filt.material) rows = rows.filter((v) => v.material === filt.material); if (filt.type) rows = rows.filter((v) => v.vessel_type === filt.type);
  if (filt.loc) rows = rows.filter((v) => String(v.location_id) === filt.loc); if (filt.status === 'active') rows = rows.filter((v) => v.is_active); if (filt.status === 'inactive') rows = rows.filter((v) => !v.is_active);
  if (filt.occ === 'full') rows = rows.filter((v) => v.stay_id); if (filt.occ === 'empty') rows = rows.filter((v) => !v.stay_id); if (filt.wine) rows = rows.filter((v) => v.wine_type === filt.wine);
  const nf = Object.values(filt).filter(Boolean).length; const sel = new Set();
  page.innerHTML = head({ title: 'Depósitos', icon: 'tank', k: 'k-admin', eyebrow: 'Configuración', sub: `${vs.length} depósitos registrados`, actions: `<button class="btn" id="scan">${ico('scan')} Escanear QR de barrica</button><button class="btn" id="imp">${ico('upload')} Importar CSV / Excel</button><button class="btn primary" id="newv">${ico('plus')} Nuevo depósito</button>` }) +
    tabs([['', 'Recipientes', 'tank'], ['ubicaciones', 'Ubicaciones', 'map']], tab, '#/depositos') +
    `<div class="board-tools"><label class="search">${ico('search')}<input id="vq" placeholder="Buscar por código…" autocomplete="off"></label><button class="btn sm ${adv ? 'primary' : ''}" id="advb">${ico('filter')} Filtros avanzados${nf ? ` (${nf})` : ''}</button><a class="btn sm" href="#/depositos${adv ? '?adv=1' : ''}">Borrar filtros</a></div>
    ${adv ? `<div class="card" style="margin-bottom:12px"><div class="row"><label class="field"><span>Recipiente</span><select class="inline" data-f="kind">${opts(KIND, filt.kind, 'Todos')}</select></label><label class="field"><span>Material</span><select class="inline" data-f="material">${opts(MATERIAL, filt.material, 'Todos')}</select></label><label class="field"><span>Uso</span><select class="inline" data-f="type">${opts(VTYPE, filt.type, 'Todos')}</select></label><label class="field"><span>Ubicación</span><select class="inline" data-f="loc"><option value="">Todas</option>${locs.map((l) => `<option value="${l.id}" ${String(l.id) === filt.loc ? 'selected' : ''}>${esc(l.path)}</option>`).join('')}</select></label><label class="field"><span>Estado</span><select class="inline" data-f="status">${opts({ active: 'Activos', inactive: 'Inactivos' }, filt.status, 'Todos')}</select></label><label class="field"><span>Contenido</span><select class="inline" data-f="occ">${opts({ full: 'Con vino', empty: 'Vacíos' }, filt.occ, 'Todos')}</select></label><label class="field"><span>Tipo de vino</span><select class="inline" data-f="wine">${opts(WINE, filt.wine, 'Todos')}</select></label></div></div>` : ''}
    <div class="table-wrap"><table class="t cards" id="vt"><thead><tr><th><input type="checkbox" id="selall" aria-label="Seleccionar todos"></th><th>Código</th><th>Tipo</th><th>Material</th><th class="num">Capacidad (L)</th><th class="num">Uva (kg)</th><th class="num">Vino (L)</th><th>Estado</th><th class="num">Llenados</th><th>Ubicación</th><th>Activo</th><th>Acciones</th></tr></thead><tbody>${rows.map(vRow).join('')}</tbody></table>${rows.length ? '' : '<div class="empty" style="border:0">Ningún recipiente coincide con los filtros.</div>'}</div>
    <div class="bulkbar" id="bulk" hidden><span><b id="bn">0</b> seleccionados</span><button class="btn" data-b="location">${ico('map')} Ubicación</button><button class="btn" data-b="status">${ico('flag')} Estado</button><button class="btn" data-b="cleaning">${ico('clean')} Limpieza</button><button class="btn" data-b="maintenance">${ico('settings')} OT mantenimiento</button><button class="btn" data-b="fill">${ico('download')} Llenado manual</button><button class="btn" data-b="note">${ico('note')} Nota</button><button class="btn" data-b="qr">${ico('print')} Imprimir QR</button><button class="btn ghost" id="bclear" style="margin-left:auto">${ico('x')}</button></div>`;
  $('#vq').oninput = (e) => { const t = e.target.value.toLowerCase(); $$('#vt tbody tr').forEach((tr) => { tr.style.display = tr.dataset.code.includes(t) ? '' : 'none'; }); };
  $('#advb').onclick = () => go('#/depositos' + qs({ ...q, adv: adv ? '' : '1' }));
  $$('[data-f]', page).forEach((s) => s.onchange = () => go('#/depositos' + qs({ ...q, adv: '1', [s.dataset.f]: s.value })));
  $$('[data-ev]', page).forEach((b) => b.onclick = () => openVesselForm(vessel(+b.dataset.ev)));
  $$('[data-qr]', page).forEach((b) => b.onclick = () => openQr(vessel(+b.dataset.qr)));
  $$('[data-exp]', page).forEach((b) => b.onclick = () => { const tr = b.closest('tr'); const v = vessel(+b.dataset.exp); const ex = tr.nextElementSibling; if (ex && ex.classList.contains('exp')) { ex.remove(); return; } tr.insertAdjacentHTML('afterend', `<tr class="exp"><td colspan="12">${[['Recipiente', KIND[v.kind]], ['Lote', v.lot_code], ['Variedad', v.varieties], ['Tonelería', v.cooperage], ['Madera', v.wood_origin], ['Grano', GRAIN[v.grain]], ['Tostado', TOAST[v.toast_level]], ['Formato', v.barrel_format], ['Compra', v.acquisition_date ? fmtD(v.acquisition_date) : null], ['Tapa flotante', v.always_full ? 'sí' : null], ['Notas', v.notes], ['Notas de barrica', v.barrel_notes]].filter((x) => x[1]).map((x) => `<b>${x[0]}:</b> ${esc(x[1])}`).join(' · ') || 'Sin datos adicionales.'}</td></tr>`); });
  const upd = () => { $('#bn').textContent = sel.size; $('#bulk').hidden = !sel.size; };
  $$('[data-sel]', page).forEach((c) => c.onchange = () => { if (c.checked) sel.add(+c.dataset.sel); else sel.delete(+c.dataset.sel); upd(); });
  $('#selall').onchange = (e) => { $$('[data-sel]', page).forEach((c) => { if (c.closest('tr').style.display !== 'none') { c.checked = e.target.checked; if (c.checked) sel.add(+c.dataset.sel); else sel.delete(+c.dataset.sel); } }); upd(); };
  $('#bclear').onclick = () => { sel.clear(); $$('[data-sel]', page).forEach((c) => { c.checked = false; }); upd(); };
  $$('[data-b]', page).forEach((b) => b.onclick = () => bulkAction(b.dataset.b, [...sel]));
  $('#newv').onclick = () => openVesselForm(null); $('#imp').onclick = () => openImport(); $('#scan').onclick = () => openScan();
}
function vRow(v) {
  const st = !v.is_active ? 'inactive' : v.barrel_status || (v.stay_id ? 'full' : 'available');
  const isB = ['barrel', 'foudre'].includes(v.kind);
  return `<tr data-code="${esc((v.code + ' ' + (v.lot_code || '') + ' ' + (v.location_name || '')).toLowerCase())}"><td>${isB ? `<input type="checkbox" data-sel="${v.id}" aria-label="Seleccionar ${esc(v.code)}">` : '<span class="muted">—</span>'}</td><td data-l="Código"><a href="#/recipiente/${v.id}"><b>${esc(v.code)}</b></a><div class="muted small">${KIND[v.kind] || ''}${v.lot_code ? ' · ' + esc(v.lot_code) : ''}</div></td><td data-l="Tipo">${VTYPE[v.vessel_type] || ''}</td><td data-l="Material">${MATERIAL[v.material] || ''}</td><td data-l="Capacidad" class="num">${fmtN(v.capacity_l)} L</td><td data-l="Uva" class="num">${v.stay_id && v.stay_unit === 'kg' ? fmtN(v.stay_volume) : '—'}</td><td data-l="Vino" class="num">${v.stay_id && v.stay_unit === 'L' ? `<a href="#/traza?lot=${v.lot_id}">${fmtN(v.stay_volume, 1)}</a>` : '—'}</td><td data-l="Estado">${isB ? `<span class="pill ${st === 'full' ? 'ok' : st === 'inactive' ? '' : st === 'cleaning' || st === 'maintenance' ? 'warn' : ''}">${BARREL_STATUS[st] || st}</span>` : '—'}</td><td data-l="Llenados" class="num">${isB ? v.fill_count || 0 : '—'}</td><td data-l="Ubicación">${esc(v.location_name || '—')}</td><td data-l="Activo">${v.is_active ? '<span class="pill ok">Activo</span>' : '<span class="pill">Inactivo</span>'}</td><td class="acts"><button class="icon-btn" data-qr="${v.id}" title="Código QR">${ico('qr')}</button> <button class="icon-btn" data-ev="${v.id}" title="Editar">${ico('edit')}</button> <button class="icon-btn" data-exp="${v.id}" title="Detalles">${ico('down')}</button></td></tr>`;
}

const barrelFields = (v = {}) => `<div class="row"><label class="field"><span>Tonelería</span><input name="cooperage" value="${esc(v.cooperage || '')}" list="coopl"><datalist id="coopl">${[...new Set(S.boot.vessels.map((x) => x.cooperage).filter(Boolean))].map((x) => `<option value="${esc(x)}">`).join('')}</datalist></label><label class="field"><span>Origen de la madera</span><select name="wood_origin">${['', 'Francia', 'Francia · Allier', 'Francia · Nevers', 'Francia · Vosges', 'Francia · Tronçais', 'EE. UU.', 'Hungría', 'Eslavonia', 'México', 'Otro'].map((x) => `<option value="${x}" ${x === (v.wood_origin || '') ? 'selected' : ''}>${x || '—'}</option>`).join('')}</select></label><label class="field"><span>Grano</span><select name="grain">${opts(GRAIN, v.grain || '', '—')}</select></label><label class="field"><span>Tostado</span><select name="toast_level">${opts(TOAST, v.toast_level || '', '—')}</select></label><label class="field"><span>Formato</span><select name="barrel_format">${['', 'Barrique 225 L', 'Bordelesa 228 L', 'Puncheon 500 L', 'Demi-muid 600 L', 'Foudre', 'Otro'].map((x) => `<option value="${x}" ${x === (v.barrel_format || '') ? 'selected' : ''}>${x || '—'}</option>`).join('')}</select></label><label class="field"><span>Fecha de compra</span><input type="date" name="acquisition_date" value="${esc(v.acquisition_date || '')}"></label><label class="field"><span>Estado</span><select name="barrel_status">${opts(BARREL_STATUS, v.barrel_status || 'available')}</select></label><label class="field"><span>Nº de llenados</span><input type="number" name="fill_count" value="${esc(v.fill_count ?? 0)}"></label></div><label class="field" style="margin-top:8px"><span>Notas de barrica</span><input name="barrel_notes" value="${esc(v.barrel_notes || '')}"></label>`;
function vesselFormFields(v = {}, { noCode = false } = {}) {
  return `<div class="row">${noCode ? '' : `<label class="field req" style="flex:1"><span>Código del depósito</span><input name="code" value="${esc(v.code || '')}" placeholder="p. ej. TK-01"></label>`}<label class="field req" style="flex:1"><span>Capacidad (L)</span><input type="number" step="1" inputmode="decimal" name="capacity_l" value="${esc(v.capacity_l || '')}" placeholder="p. ej. 2000"></label></div>
    <div class="row" style="margin-top:12px"><label class="field req"><span>Uso</span><select name="vessel_type">${opts(VTYPE, v.vessel_type || 'storage')}</select></label><label class="field req"><span>Material</span><select name="material">${opts(MATERIAL, v.material || 'stainless_steel')}</select></label><label class="field req"><span>Tipo de recipiente</span><select name="kind">${opts(KIND, v.kind || 'tank')}</select></label></div>
    <div class="row" style="margin-top:12px"><label class="field"><span>Ubicación en la bodega</span><select name="location_id"><option value="">Sin ubicación</option>${S.boot.locations.map((l) => `<option value="${l.id}" ${l.id === v.location_id ? 'selected' : ''}>${esc(l.path)}</option>`).join('')}</select></label></div>
    <div class="row" style="margin-top:12px"><label class="toggle"><input type="checkbox" name="is_active" ${v.is_active === 0 ? '' : 'checked'}> Depósito activo</label><label class="toggle"><input type="checkbox" name="always_full" ${v.always_full ? 'checked' : ''}> Siempre lleno (tapa flotante / capacidad variable)</label></div><div class="help">Tapa flotante: no tiene espacio de cabeza, así que no entra en las alertas de depósitos por rellenar.</div>
    <details ${['barrel', 'foudre'].includes(v.kind) ? 'open' : ''} style="margin-top:12px"><summary class="muted small">Datos de barrica (tonelería, madera, grano, tostado, formato…)</summary><div style="margin-top:8px">${barrelFields(v)}</div></details>
    <label class="field" style="margin-top:12px"><span>Notas</span><textarea name="notes" rows="2">${esc(v.notes || '')}</textarea></label>`;
}
export function openVesselForm(v) {
  if (v) { formModal({ title: `Editar ${v.code}`, eyebrow: 'Depósitos', okLabel: 'Guardar', body: vesselFormFields(v), onSave: async (b) => { await api(`/vessels/${v.id}`, { method: 'PUT', body: b }); closeModal(); toast('Depósito guardado'); await reload(); route(); } }); return; }
  // Crear: una pestaña «Crear uno» y otra «Crear secuencia» en el mismo modal
  let tab = 'one';
  const draw = () => {
    const m = modal('Nuevo depósito', `<div class="seg" style="margin-bottom:14px"><button type="button" data-t="one" aria-pressed="${tab === 'one'}">${ico('tank')}Crear uno</button><button type="button" data-t="seq" aria-pressed="${tab === 'seq'}">${ico('layers')}Crear secuencia</button></div>` +
      (tab === 'one' ? vesselFormFields({}) : `<div class="row"><label class="field req"><span>Prefijo</span><input name="prefix" placeholder="BBL"></label><label class="field"><span>Inicio</span><input type="number" name="start" value="1"></label><label class="field req"><span>Cantidad</span><input type="number" name="count" value="5"></label><label class="field"><span>Dígitos</span><input type="number" name="digits" value="3"></label></div><div class="help" style="margin-bottom:12px">Genera PREFIJO-001, PREFIJO-002… con los mismos datos.</div>` + vesselFormFields({ kind: 'barrel', vessel_type: 'aging', material: 'oak', capacity_l: 225 }, { noCode: true })),
      `<button class="btn" data-x="cancel">Cancelar</button><button class="btn primary" data-x="ok">${tab === 'one' ? 'Crear depósito' : 'Crear secuencia'}</button>`, { eyebrow: 'Depósitos' });
    $$('[data-t]', m).forEach((b) => b.onclick = () => { tab = b.dataset.t; draw(); });
    $('[data-x=ok]', m).onclick = async () => { try { if (tab === 'one') { await api('/vessels', { method: 'POST', body: formValues(m) }); toast('Depósito creado'); } else { const r = await api('/vessels/sequence', { method: 'POST', body: formValues(m) }); toast(`${r.created.length} recipientes creados`); } closeModal(); await reload(); route(); } catch (e) { showError(m, e.message); } };
  };
  draw();
}
function openImport() {
  importModal({ title: 'Importar depósitos desde CSV', help: 'Columnas (coma o punto y coma): <b>codigo, capacidad_l, tipo, material, recipiente, activo, ubicacion, notas</b> (+ toneleria, wood_origin, toast_level, barrel_format, acquisition_date). Valores en español, portugués o inglés. Los códigos ya existentes se omiten.', map: { codigo: 'code', code: 'code', código: 'code', capacidade_l: 'capacity_l', capacidad_l: 'capacity_l', capacidad: 'capacity_l', capacity_l: 'capacity_l', tipo: 'vessel_type', uso: 'vessel_type', vessel_type: 'vessel_type', material: 'material', vasilha: 'kind', recipiente: 'kind', kind: 'kind', ativo: 'is_active', activo: 'is_active', is_active: 'is_active', cooperage: 'cooperage', toneleria: 'cooperage', tonelería: 'cooperage', wood_origin: 'wood_origin', toast_level: 'toast_level', barrel_format: 'barrel_format', acquisition_date: 'acquisition_date', notas: 'notes', notes: 'notes', ubicacion: 'location', ubicación: 'location', location: 'location', always_full: 'always_full', siempre_lleno: 'always_full' }, template: { name: 'depositos.csv', cols: [['code', 'codigo'], ['capacity_l', 'capacidad_l'], ['vessel_type', 'tipo'], ['material', 'material'], ['kind', 'recipiente'], ['is_active', 'activo'], ['location', 'ubicacion']], rows: [{ code: 'TK-01', capacity_l: 2000, vessel_type: 'fermentación', material: 'inox', kind: 'depósito', is_active: 'si', location: 'Sala principal' }] }, preview: (rows) => `<div class="table-wrap" style="margin-top:6px;max-height:260px;overflow:auto"><table class="t"><thead><tr><th>Código</th><th class="num">Cap.</th><th>Tipo</th><th>Material</th><th>Recipiente</th></tr></thead><tbody>${rows.slice(0, 200).map((r) => `<tr><td>${esc(r.code)}</td><td class="num">${esc(r.capacity_l)}</td><td>${esc(r.vessel_type)}</td><td>${esc(r.material)}</td><td>${esc(r.kind)}</td></tr>`).join('')}</tbody></table></div>`, onImport: async (rows) => { const r = await api('/vessels/import', { method: 'POST', body: { rows } }); toast(`${r.created} creados${r.skipped.length ? `, ${r.skipped.length} ya existían` : ''}`); await reload(); route(); } });
}
function openScan() {
  const m = modal('Escanear código QR', `<div class="qr-box"><video id="cam" playsinline style="width:100%;max-width:360px;border-radius:12px;background:#000;aspect-ratio:1"></video><div id="scanmsg" class="muted small">Apunta la cámara al QR del recipiente.</div><div class="sec-title">O escribe el código</div><label class="search" style="width:100%">${ico('search')}<input id="scancode" placeholder="TK-13" autocomplete="off"></label></div>`, `<button class="btn" data-x="cancel">Cerrar</button>`, { eyebrow: 'Depósitos', narrow: true });
  let stream = null, timer = null;
  const stop = () => { if (timer) clearInterval(timer); if (stream) stream.getTracks().forEach((t) => t.stop()); };
  $('.x', m).addEventListener('click', stop); $('[data-x=cancel]', m).addEventListener('click', stop);
  const open = (text) => { const mm = String(text).match(/recipiente\/(\d+)/); if (mm) { stop(); closeModal(); go('#/recipiente/' + mm[1]); return true; } const v = S.boot.vessels.find((x) => x.code.toLowerCase() === String(text).trim().toLowerCase()); if (v) { stop(); closeModal(); go('#/recipiente/' + v.id); return true; } return false; };
  $('#scancode', m).onkeydown = (e) => { if (e.key === 'Enter' && !open(e.target.value)) toast('No hay ningún recipiente con ese código', true); };
  (async () => { try { if (!navigator.mediaDevices?.getUserMedia) throw new Error('sin cámara'); stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }); const v = $('#cam', m); v.srcObject = stream; await v.play(); if (!('BarcodeDetector' in window)) { $('#scanmsg', m).textContent = 'Este navegador no decodifica QR; escribe el código.'; return; } const det = new window.BarcodeDetector({ formats: ['qr_code'] }); timer = setInterval(async () => { try { const codes = await det.detect(v); if (codes[0] && !open(codes[0].rawValue)) $('#scanmsg', m).textContent = 'QR no reconocido: ' + codes[0].rawValue; } catch { /* frame */ } }, 400); } catch { $('#cam', m).style.display = 'none'; $('#scanmsg', m).textContent = 'Cámara no disponible: escribe el código del recipiente.'; } })();
}
function bulkAction(action, ids) {
  if (!ids.length) return;
  if (action === 'qr') { const w = window.open('', '_blank'); w.document.write(`<!doctype html><title>QR</title><style>body{font-family:sans-serif;display:grid;grid-template-columns:repeat(3,1fr);gap:18px;padding:18px}figure{margin:0;text-align:center;page-break-inside:avoid}svg{width:180px;height:180px}figcaption{font-weight:700;font-size:18px;margin-top:6px}small{display:block;color:#555}</style>`); Promise.all(ids.map((id) => fetch(`/api/vessels/${id}/qr.svg`).then((r) => r.text()).then((svg) => { const v = vessel(id); return `<figure>${svg}<figcaption>${esc(v.code)}</figcaption><small>${KIND[v.kind] || ''} · ${fmtN(v.capacity_l)} L</small></figure>`; }))).then((hs) => { w.document.write(hs.join('')); w.document.close(); setTimeout(() => w.print(), 400); }); return; }
  const titles = { location: 'Cambiar ubicación', status: 'Cambiar estado', cleaning: 'Registrar limpieza', maintenance: 'Orden de mantenimiento', fill: 'Registrar llenado manual', note: 'Añadir nota' };
  const body = { location: `<label class="field req"><span>Ubicación</span><select name="location_id"><option value="">Sin ubicación</option>${S.boot.locations.map((l) => `<option value="${l.id}">${esc(l.path)}</option>`).join('')}</select></label>`, status: `<label class="field req"><span>Estado</span><select name="status">${opts(BARREL_STATUS, 'available')}</select></label><div class="help">«Inactiva» desactiva el recipiente; los demás estados son informativos.</div>`, cleaning: `<div class="row"><label class="field"><span>Fecha</span><input type="date" name="date" value="${today()}"></label><label class="field"><span>Quién</span><input name="by_name" value="${esc(me()?.name || '')}"></label></div><label class="field" style="margin-top:12px"><span>Método</span><input name="method" placeholder="Agua caliente, sosa, ozono…"></label><label class="field" style="margin-top:12px"><span>Notas</span><input name="notes"></label>`, maintenance: `<label class="field req"><span>Descripción de la OT</span><textarea name="text" rows="3" placeholder="Revisar aros, cambiar grifo, rehidratar…"></textarea></label><label class="field" style="margin-top:12px"><span>Responsable</span><input name="by_name" value="${esc(me()?.name || '')}"></label>`, fill: `<div class="row"><label class="field"><span>Fecha</span><input type="date" name="date" value="${today()}"></label><label class="field"><span>Quién</span><input name="by_name" value="${esc(me()?.name || '')}"></label></div><label class="field" style="margin-top:12px"><span>Nota</span><input name="text" placeholder="Llenado registrado a mano"></label><div class="help">Suma 1 al contador de llenados; no mueve vino.</div>`, note: `<label class="field req"><span>Nota</span><textarea name="text" rows="3"></textarea></label><label class="field" style="margin-top:12px"><span>Quién</span><input name="by_name" value="${esc(me()?.name || '')}"></label>` }[action];
  formModal({ title: `${titles[action]} · ${ids.length} recipientes`, eyebrow: 'Acción en lote', narrow: true, okLabel: 'Aplicar', body: `<div class="help" style="margin-bottom:10px">${ids.map((id) => `<code>${esc(vessel(id).code)}</code>`).join(' ')}</div>` + body, onSave: async (b) => { await api('/vessels/bulk', { method: 'POST', body: { ids, action, ...b } }); closeModal(); toast(`Aplicado a ${ids.length} recipientes`); await reload(); route(); } });
}

// ================================================================ UBICACIONES
export async function viewLocations(page, embedded = false) {
  crumbs('Configuración', '<a href="#/depositos">Depósitos</a>', 'Ubicaciones');
  const r = await api('/locations'); const locs = r.locations;
  const kids = (pid) => locs.filter((l) => (l.parent_id || null) === pid);
  const tree = (pid, depth) => kids(pid).map((l) => `<div class="item" style="margin-left:${depth * 22}px"><span class="pill k" style="--k:var(--admin);--kb:var(--admin-soft)">${LOC_KIND[l.kind] || l.kind}</span><div class="body"><div class="t">${esc(l.name)}</div><div class="m">${l.vessels} recipiente${l.vessels === 1 ? '' : 's'}${l.room ? ' · ' + esc(l.room) : ''}</div></div><button class="btn sm" data-add="${l.id}">${ico('plus')} Dentro</button><button class="icon-btn" data-ed="${l.id}">${ico('edit')}</button><button class="icon-btn" data-del="${l.id}">${ico('trash')}</button></div>` + tree(l.id, depth + 1)).join('');
  page.innerHTML = head({ title: 'Depósitos', icon: 'tank', k: 'k-admin', eyebrow: 'Configuración', sub: 'Sala de barricas y ubicaciones: jerarquía edificio › sala › fila › estante. Cada recipiente se asigna a una ubicación; el tablero agrupa por ella.', actions: `<button class="btn primary" id="newl">${ico('plus')} Nueva ubicación</button>` }) +
    tabs([['', 'Recipientes', 'tank'], ['ubicaciones', 'Ubicaciones', 'map']], 'ubicaciones', '#/depositos') +
    (locs.length ? `<div class="rowlist">${tree(null, 0)}</div>` : empty('Sin ubicaciones', 'Crea edificios, salas, filas y estantes para situar cada recipiente.', '<button class="btn primary" id="newl2">Nueva ubicación</button>', 'map'));
  const nw = (parent) => openLocation(null, parent, locs); $('#newl').onclick = () => nw(null); if ($('#newl2')) $('#newl2').onclick = () => nw(null);
  $$('[data-add]', page).forEach((b) => b.onclick = () => nw(+b.dataset.add));
  $$('[data-ed]', page).forEach((b) => b.onclick = () => openLocation(locs.find((l) => l.id === +b.dataset.ed), null, locs));
  $$('[data-del]', page).forEach((b) => b.onclick = async () => { const l = locs.find((x) => x.id === +b.dataset.del); if (!(await confirmDialog('Eliminar ubicación', `¿Eliminar <b>${esc(l.name)}</b>? Los recipientes que contiene quedan sin ubicación.`, 'Eliminar', true))) return; try { await api(`/locations/${l.id}`, { method: 'DELETE' }); toast('Ubicación eliminada'); await reload(); route(); } catch (e) { toast(e.message, true); } });
}

function openLocation(l, parent, locs) {
  const v = l || { parent_id: parent, kind: parent ? ({ building: 'room', room: 'row', row: 'shelf' }[locs.find((x) => x.id === parent)?.kind] || 'shelf') : 'building' };
  formModal({ title: l ? 'Editar ubicación' : 'Nueva ubicación', eyebrow: 'Ubicaciones', narrow: true, okLabel: 'Guardar', body: `<label class="field req"><span>Nombre</span><input name="name" value="${esc(v.name || '')}" placeholder="Sala de barricas · fila 1"></label><div class="row" style="margin-top:12px"><label class="field"><span>Tipo</span><select name="kind">${opts(LOC_KIND, v.kind)}</select></label><label class="field"><span>Dentro de</span><select name="parent_id"><option value="">— Raíz —</option>${locs.filter((x) => !l || x.id !== l.id).map((x) => `<option value="${x.id}" ${x.id === v.parent_id ? 'selected' : ''}>${esc(x.path)}</option>`).join('')}</select></label></div><label class="field" style="margin-top:12px"><span>Orden</span><input type="number" name="sort" value="${esc(v.sort ?? 0)}"></label>`,
    onSave: async (b) => { await api(l ? `/locations/${l.id}` : '/locations', { method: l ? 'PUT' : 'POST', body: b }); closeModal(); toast('Ubicación guardada'); await reload(); route(); } });
}

// ================================================================ USUARIOS
